#!/usr/bin/env python3
import sys, re, json, math, copy
from dataclasses import dataclass
from typing import Any, List, Tuple

VERSION = "v0.0.0"
EMPTY = object()

@dataclass
class Obj:
    pairs: List[Tuple[Any, Any]]

@dataclass
class SpecialFloat:
    kind: str  # 'inf', '-inf', 'nan'

@dataclass
class DateVal:
    toml_text: str
    json_text: str

# ----------------------------- helpers -----------------------------

def deep_copy(v):
    return copy.deepcopy(v)

def is_obj(v): return isinstance(v, Obj)
def is_special(v): return isinstance(v, SpecialFloat)
def is_date(v): return isinstance(v, DateVal)

def obj_get_pair(obj: Obj, key: str):
    for i,(k,v) in enumerate(obj.pairs):
        if k == key:
            return i,v
    return -1,None

def obj_set(obj: Obj, key: str, val: Any, allow_dup=False):
    if not allow_dup:
        i,_ = obj_get_pair(obj,key)
        if i >= 0:
            obj.pairs[i] = (key,val)
            return
    obj.pairs.append((key,val))

def key_to_string(k):
    if isinstance(k, str):
        return k
    if k is None:
        return "null"
    if isinstance(k, bool):
        return "true" if k else "false"
    if isinstance(k, int) and not isinstance(k, bool):
        return str(k)
    if isinstance(k, float):
        # YAML's map-key conversion tends to use a compact non-.0 spelling.
        s = go_float_json(k)
        return s
    if isinstance(k, SpecialFloat):
        return {"inf":"Infinity","-inf":"-Infinity","nan":"NaN"}[k.kind]
    if isinstance(k, DateVal):
        return k.json_text
    # complex YAML keys are converted to compact JSON-looking strings.
    return encode_json_compact(k, False)

# ----------------------------- CLI -----------------------------

def usage(prog):
    return f"""Usage: {prog} [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version
"""

def parse_flags(argv):
    valid = set("ytjcrneikhv")
    invalid = []
    conv = []
    opts = {"n":False,"e":False,"i":False,"k":False,"h":False,"v":False}
    for arg in argv[1:]:
        s = arg.replace('-', '')
        for ch in s:
            if ch not in valid:
                if ch not in invalid:
                    invalid.append(ch)
            else:
                if ch in "neikhv":
                    opts[ch] = True
                if ch == 'r':
                    conv.extend(['j','y'])
                elif ch in 'ytjc':
                    conv.append(ch)
    if len(conv) == 0:
        src,dst = 'y','j'
    elif len(conv) == 1:
        src,dst = conv[0],'j'
    else:
        src,dst = conv[-2],conv[-1]
    return invalid, opts, src, dst

# ----------------------------- JSON -----------------------------

class JSONParseError(Exception): pass

def parse_json_text(text):
    def bad_const(x):
        # Go's encoding/json rejects these as an invalid starting character.
        raise JSONParseError(f"invalid character '{x[0]}' looking for beginning of value")
    try:
        return json.loads(text, object_pairs_hook=lambda pairs: Obj(pairs),
                          parse_int=int, parse_float=float, parse_constant=bad_const)
    except JSONParseError:
        raise
    except json.JSONDecodeError as e:
        raise JSONParseError(go_json_error(text, e))

def printable_char(ch):
    if ch == '': return ''
    if ch == '\n': return '\\n'
    if ch == '\t': return '\\t'
    return ch

def go_json_error(text, e):
    stripped = text.strip()
    if stripped == "":
        return "unexpected end of JSON input"
    msg = e.msg
    pos = e.pos
    ch = text[pos] if pos < len(text) else ''
    # Common encoding/json messages used by yj.
    if msg.startswith('Expecting property name enclosed in double quotes'):
        if ch == '}':
            return "invalid character '}' looking for beginning of object key string"
        if ch == ']' :
            return "invalid character ']' looking for beginning of object key string"
        return f"invalid character '{printable_char(ch)}' looking for beginning of object key string"
    if msg.startswith('Expecting value'):
        if ch:
            return f"invalid character '{printable_char(ch)}' looking for beginning of value"
        return "unexpected end of JSON input"
    if msg.startswith('Expecting ':' delimiter'):
        if ch:
            return f"invalid character '{printable_char(ch)}' after object key"
        return "unexpected end of JSON input"
    if msg.startswith('Expecting ',' delimiter'):
        if ch:
            return f"invalid character '{printable_char(ch)}' after array element"
        return "unexpected end of JSON input"
    if msg.startswith('Extra data'):
        return f"invalid character '{printable_char(ch)}' after top-level value"
    if 'Unterminated string' in msg:
        return "unexpected end of JSON input"
    if ch:
        return f"invalid character '{printable_char(ch)}' looking for beginning of value"
    return msg

def json_escape_string(s, escape_html=False):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ch == '<' and escape_html: out.append('\\u003c')
        elif ch == '>' and escape_html: out.append('\\u003e')
        elif ch == '&' and escape_html: out.append('\\u0026')
        elif o == 0x2028: out.append('\\u2028')
        elif o == 0x2029: out.append('\\u2029')
        elif o < 0x20: out.append('\\u%04x' % o)
        else: out.append(ch)
    out.append('"')
    return ''.join(out)

def normalize_exp(expstr):
    sign = '+' if int(expstr) >= 0 else '-'
    n = abs(int(expstr))
    return sign + str(n)

def dec_from_scientific(rep):
    # rep like -1.234e+10; return decimal expansion preserving shortest mantissa digits.
    neg = rep.startswith('-')
    if neg: rep = rep[1:]
    mant, exp = re.split('[eE]', rep)
    e = int(exp)
    if '.' in mant:
        a,b = mant.split('.')
        digits = a + b
        decpos = len(a) + e
    else:
        digits = mant
        decpos = len(digits) + e
    digits = digits.lstrip('0') or '0'
    # adjust decpos if stripping zeros before decimal changed? For mantissas from repr, leading zero only for 0.x not used in sci.
    if decpos <= 0:
        res = '0.' + '0'*(-decpos) + digits
    elif decpos >= len(digits):
        res = digits + '0'*(decpos-len(digits))
    else:
        res = digits[:decpos] + '.' + digits[decpos:]
    if '.' in res:
        res = res.rstrip('0').rstrip('.')
    if neg and res != '0': res = '-' + res
    return res

def sci_normalize(rep, min_exp_digits=1):
    neg = rep.startswith('-')
    if neg: rep = rep[1:]
    mant, exp = re.split('[eE]', rep)
    if mant.endswith('.0'):
        mant = mant[:-2]
    sign = '+' if int(exp) >= 0 else '-'
    n = str(abs(int(exp)))
    if len(n) < min_exp_digits:
        n = '0'*(min_exp_digits-len(n)) + n
    return ('-' if neg else '') + mant + 'e' + sign + n

def go_float_json(f):
    if math.isnan(f): return 'null'
    if math.isinf(f): return '1.7976931348623157e+308' if f > 0 else '-1.7976931348623157e+308'
    if f == 0:
        return '-0' if math.copysign(1.0, f) < 0 else '0'
    af = abs(f)
    rep = repr(f)
    # Python may use e-07; Go JSON uses e-7, and decimal for [1e-6,1e21).
    if 'e' in rep or 'E' in rep:
        if af >= 1e-6 and af < 1e21:
            return dec_from_scientific(rep)
        return sci_normalize(rep, 1)
    if rep.endswith('.0'):
        return rep[:-2]
    return rep

def yaml_float(f):
    if math.isnan(f): return '.nan'
    if math.isinf(f): return '.inf' if f > 0 else '-.inf'
    if f == 0:
        return '-0.0' if math.copysign(1.0, f) < 0 else '0.0'
    af = abs(f)
    rep = repr(f)
    # yaml.v2 tends to scientific for >=1e6 and <1e-4, with two exponent digits.
    if af >= 1e6 or af < 1e-4:
        if 'e' not in rep and 'E' not in rep:
            rep = f"{f:.15e}".rstrip('0').rstrip('.')
        return sci_normalize(rep, 2)
    # decimal, preserving .0 for integer floats
    if 'e' in rep or 'E' in rep:
        s = dec_from_scientific(rep)
    else:
        s = rep
    if '.' not in s:
        s += '.0'
    return s

def toml_float(f):
    if math.isnan(f): return 'nan'
    if math.isinf(f): return '+inf' if f > 0 else '-inf'
    rep = repr(f)
    if 'e' in rep or 'E' in rep:
        s = dec_from_scientific(rep)
    else:
        s = rep
    if '.' not in s:
        s += '.0'
    return s

def encode_json_compact(v, escape_html=False):
    return encode_json(v, escape_html=escape_html, indent=None)

def encode_json(v, escape_html=False, indent=None, level=0):
    if v is EMPTY:
        return ''
    if isinstance(v, Obj):
        if indent is None:
            parts=[]
            for k,val in v.pairs:
                parts.append(json_escape_string(key_to_string(k), escape_html)+":"+encode_json(val, escape_html, None, level))
            return "{"+",".join(parts)+"}"
        if not v.pairs:
            return "{}"
        sp=' '*indent
        cur=' '*(level*indent)
        nxt=' '*((level+1)*indent)
        lines=['{']
        for i,(k,val) in enumerate(v.pairs):
            comma=',' if i < len(v.pairs)-1 else ''
            lines.append(nxt+json_escape_string(key_to_string(k), escape_html)+': '+encode_json(val, escape_html, indent, level+1)+comma)
        lines.append(cur+'}')
        return '\n'.join(lines)
    if isinstance(v, list):
        if indent is None:
            return '['+','.join(encode_json(x, escape_html, None, level) for x in v)+']'
        if not v:
            return '[]'
        cur=' '*(level*indent)
        nxt=' '*((level+1)*indent)
        lines=['[']
        for i,x in enumerate(v):
            comma=',' if i < len(v)-1 else ''
            lines.append(nxt+encode_json(x, escape_html, indent, level+1)+comma)
        lines.append(cur+']')
        return '\n'.join(lines)
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        return go_float_json(v)
    if isinstance(v, SpecialFloat):
        if v.kind == 'nan': return 'null'
        return '1.7976931348623157e+308' if v.kind == 'inf' else '-1.7976931348623157e+308'
    if isinstance(v, DateVal):
        return json_escape_string(v.json_text, escape_html)
    return json_escape_string(str(v), escape_html)

# ----------------------------- YAML parser -----------------------------

@dataclass
class YLine:
    indent: int
    content: str
    raw: str
    lineno: int

class YAMLParseError(Exception): pass

class YAMLParser:
    def __init__(self, text):
        self.text = text.replace('\r\n','\n').replace('\r','\n')
        self.lines = self.make_lines(self.text)
        self.anchors = {}

    def make_lines(self, text):
        raw_lines = text.split('\n')
        out=[]; seen_doc=False
        i=0
        while i < len(raw_lines):
            raw = raw_lines[i]
            stripped = raw.strip()
            if stripped == '---':
                if seen_doc or out:
                    break
                seen_doc=True; i+=1; continue
            if stripped == '...':
                break
            if stripped == '' or stripped.startswith('#'):
                i+=1; continue
            no = strip_yaml_comment(raw)
            if no.strip() == '':
                i+=1; continue
            indent = len(no) - len(no.lstrip(' '))
            out.append(YLine(indent, no.strip(), raw, i))
            i+=1
        return out

    def parse(self):
        if self.text.strip() == '':
            return EMPTY
        if not self.lines:
            return EMPTY
        val, idx = self.parse_block(0, self.lines[0].indent)
        return val

    def skip_blank(self, idx):
        return idx

    def parse_block(self, idx, indent):
        if idx >= len(self.lines):
            return None, idx
        line = self.lines[idx]
        if line.indent < indent:
            return None, idx
        if line.content.startswith('-') and (line.content == '-' or line.content.startswith('- ')):
            return self.parse_seq(idx, line.indent)
        return self.parse_map(idx, line.indent)

    def parse_map(self, idx, indent):
        pairs=[]
        while idx < len(self.lines):
            line=self.lines[idx]
            if line.indent < indent: break
            if line.indent > indent:
                break
            c=line.content
            if c.startswith('-') and (c == '-' or c.startswith('- ')):
                break
            if c.startswith('?') and (c == '?' or c.startswith('? ')):
                keyexpr = c[1:].strip()
                if keyexpr:
                    keyval = parse_yaml_inline(keyexpr, self)
                    idx += 1
                else:
                    keyval, idx = self.parse_block(idx+1, indent+2)
                if idx < len(self.lines) and self.lines[idx].indent == indent and self.lines[idx].content.startswith(':'):
                    rest = self.lines[idx].content[1:].strip()
                    val, idx = self.parse_value_after(rest, idx, indent)
                else:
                    val = None
                pairs.append((key_to_string(keyval), val))
                continue
            pos = find_top_colon(c)
            if pos < 0:
                # root scalar fallback
                if not pairs:
                    return parse_yaml_inline(c, self), idx+1
                break
            keyraw = c[:pos].strip()
            rest = c[pos+1:].strip()
            keyval = parse_yaml_inline(keyraw, self, is_key=True)
            key = key_to_string(keyval)
            val, idx = self.parse_value_after(rest, idx, indent)
            pairs.append((key,val))
        return Obj(pairs), idx

    def parse_value_after(self, rest, idx, indent):
        if rest in ('|','|-','|+','>','>-','>+') or rest.startswith('|') or rest.startswith('>'):
            val, nidx = self.parse_block_scalar(idx+1, indent, rest)
            return val, nidx
        if rest == '':
            nidx = idx+1
            if nidx < len(self.lines) and self.lines[nidx].indent > indent:
                return self.parse_block(nidx, self.lines[nidx].indent)
            return None, nidx
        return parse_yaml_inline(rest, self), idx+1

    def parse_seq(self, idx, indent):
        arr=[]
        while idx < len(self.lines):
            line=self.lines[idx]
            if line.indent < indent: break
            if line.indent > indent: break
            c=line.content
            if not (c == '-' or c.startswith('- ')): break
            item = c[1:].strip()
            if item == '':
                if idx+1 < len(self.lines) and self.lines[idx+1].indent > indent:
                    val, idx = self.parse_block(idx+1, self.lines[idx+1].indent)
                else:
                    val=None; idx+=1
                arr.append(val); continue
            if item in ('|','|-','|+','>','>-','>+') or item.startswith('|') or item.startswith('>'):
                val, idx = self.parse_block_scalar(idx+1, indent, item)
                arr.append(val); continue
            # inline nested sequence like "- - 2"
            if item.startswith('- '):
                val = parse_yaml_inline_seq_from_dash(item, self)
                idx += 1
                arr.append(val); continue
            pos=find_top_colon(item)
            if pos >= 0 and not item.startswith('{'):
                keyraw=item[:pos].strip(); rest=item[pos+1:].strip()
                key=key_to_string(parse_yaml_inline(keyraw,self,is_key=True))
                if rest == '':
                    if idx+1 < len(self.lines) and self.lines[idx+1].indent > indent:
                        v, nidx = self.parse_block(idx+1, self.lines[idx+1].indent)
                        idx = nidx
                    else:
                        v=None; idx+=1
                else:
                    v=parse_yaml_inline(rest,self); idx+=1
                obj=Obj([(key,v)])
                # merge following mapping lines indented under this sequence item
                if idx < len(self.lines) and self.lines[idx].indent > indent:
                    more, nidx = self.parse_map(idx, self.lines[idx].indent)
                    if isinstance(more, Obj):
                        obj.pairs.extend(more.pairs)
                        idx = nidx
                arr.append(obj); continue
            val=parse_yaml_inline(item,self); idx+=1
            # ignore continuation for simple scalars except nested map/list for null-like item
            arr.append(val)
        return arr, idx

    def parse_block_scalar(self, idx, parent_indent, indicator):
        literal = indicator.startswith('|')
        strip_final = '-' in indicator
        keep_final = '+' in indicator
        # first non-empty line indent
        start=idx
        minindent=None
        while idx < len(self.lines) and self.lines[idx].indent > parent_indent:
            if minindent is None or self.lines[idx].indent < minindent:
                minindent = self.lines[idx].indent
            idx += 1
        if minindent is None:
            return ('', start)
        texts=[]
        for j in range(start, idx):
            raw = self.lines[j].raw
            # preserve text after minindent columns
            part = raw[minindent:] if len(raw) >= minindent else ''
            texts.append(part)
        if literal:
            s='\n'.join(texts)
        else:
            # simple folded style: non-empty physical lines join by spaces; blank lines by newlines.
            res=[]
            for t in texts:
                if t.strip() == '':
                    res.append('\n')
                else:
                    if res and not str(res[-1]).endswith('\n'):
                        res.append(' ')
                    res.append(t.strip())
            s=''.join(res)
        if not strip_final:
            s += '\n'
        return s, idx


def strip_yaml_comment(line):
    in_s=False; in_d=False; esc=False
    for i,ch in enumerate(line):
        if in_d:
            if esc: esc=False
            elif ch == '\\': esc=True
            elif ch == '"': in_d=False
        elif in_s:
            if ch == "'": in_s=False
        else:
            if ch == '"': in_d=True
            elif ch == "'": in_s=True
            elif ch == '#':
                if i == 0 or line[i-1].isspace():
                    return line[:i].rstrip()
    return line.rstrip()

def find_top_colon(s):
    in_s=False; in_d=False; esc=False; depth=0
    for i,ch in enumerate(s):
        if in_d:
            if esc: esc=False
            elif ch == '\\': esc=True
            elif ch == '"': in_d=False
        elif in_s:
            if ch == "'":
                if i+1 < len(s) and s[i+1] == "'":
                    continue
                in_s=False
        else:
            if ch == '"': in_d=True
            elif ch == "'": in_s=True
            elif ch in '[{(': depth+=1
            elif ch in ']})': depth=max(0,depth-1)
            elif ch == ':' and depth == 0:
                # YAML allows a:b as a plain scalar/key; colon separates if followed by space/end.
                if i+1 == len(s) or s[i+1].isspace():
                    return i
    return -1

class FlowParser:
    def __init__(self, s, mode='yaml', yp=None):
        self.s=s; self.i=0; self.mode=mode; self.yp=yp
    def skip(self):
        while self.i < len(self.s) and self.s[self.i].isspace(): self.i+=1
    def peek(self):
        self.skip(); return self.s[self.i] if self.i < len(self.s) else ''
    def consume(self,ch=None):
        self.skip()
        if ch is not None and (self.i>=len(self.s) or self.s[self.i]!=ch):
            raise ValueError('expected '+ch)
        c=self.s[self.i]; self.i+=1; return c
    def parse(self):
        v=self.value(); self.skip(); return v
    def value(self):
        self.skip()
        if self.i >= len(self.s): return ''
        ch=self.s[self.i]
        if ch == '"': return self.dq()
        if ch == "'": return self.sq()
        if ch == '[': return self.arr()
        if ch == '{': return self.obj()
        return self.bare()
    def dq(self):
        self.i+=1; out=[]; esc=False
        while self.i < len(self.s):
            ch=self.s[self.i]; self.i+=1
            if esc:
                maps={'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f','"':'"','\\':'\\','/':'/'}
                if ch == 'u' and self.i+4 <= len(self.s):
                    hx=self.s[self.i:self.i+4]; self.i+=4
                    try: out.append(chr(int(hx,16)))
                    except: out.append('\\u'+hx)
                elif ch == 'U' and self.i+8 <= len(self.s):
                    hx=self.s[self.i:self.i+8]; self.i+=8
                    try: out.append(chr(int(hx,16)))
                    except: out.append('\\U'+hx)
                else:
                    out.append(maps.get(ch,ch))
                esc=False
            elif ch == '\\': esc=True
            elif ch == '"': break
            else: out.append(ch)
        return ''.join(out)
    def sq(self):
        self.i+=1; out=[]
        while self.i < len(self.s):
            ch=self.s[self.i]; self.i+=1
            if ch == "'":
                if self.i < len(self.s) and self.s[self.i] == "'":
                    out.append("'"); self.i+=1; continue
                break
            out.append(ch)
        return ''.join(out)
    def arr(self):
        self.consume('['); arr=[]
        while True:
            self.skip()
            if self.i >= len(self.s): break
            if self.s[self.i] == ']': self.i+=1; break
            arr.append(self.value())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ',': self.i+=1; continue
            if self.i < len(self.s) and self.s[self.i] == ']': self.i+=1; break
        return arr
    def obj(self):
        self.consume('{'); pairs=[]
        while True:
            self.skip()
            if self.i >= len(self.s): break
            if self.s[self.i] == '}': self.i+=1; break
            key = self.key_token()
            self.skip()
            if self.i < len(self.s) and self.s[self.i] in ':=':
                self.i += 1
            val = self.value()
            pairs.append((key_to_string(key), val))
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ',': self.i+=1; continue
            if self.i < len(self.s) and self.s[self.i] == '}': self.i+=1; break
        return Obj(pairs)
    def key_token(self):
        self.skip()
        if self.i < len(self.s) and self.s[self.i] == '"': return self.dq()
        if self.i < len(self.s) and self.s[self.i] == "'": return self.sq()
        start=self.i; depth=0
        while self.i < len(self.s):
            ch=self.s[self.i]
            if ch in '[{(': depth+=1
            elif ch in ']})':
                if depth==0: break
                depth-=1
            if depth==0 and ch in ':=': break
            self.i += 1
        token=self.s[start:self.i].strip()
        return parse_yaml_scalar(token, self.yp, is_key=True) if self.mode=='yaml' else token
    def bare(self):
        start=self.i; depth=0
        while self.i < len(self.s):
            ch=self.s[self.i]
            if ch in '[{(': depth+=1
            elif ch in ']})':
                if depth==0: break
                depth-=1
            if depth==0 and ch in ',]}': break
            self.i += 1
        token=self.s[start:self.i].strip()
        if self.mode == 'yaml': return parse_yaml_scalar(token, self.yp)
        if self.mode == 'toml': return parse_toml_scalar(token)
        return parse_hcl_scalar(token)

def parse_yaml_inline(s, yp=None, is_key=False):
    s=s.strip()
    # anchors and aliases
    if yp is not None:
        if s.startswith('*') and re.match(r'^\*[A-Za-z0-9_-]+$', s):
            return deep_copy(yp.anchors.get(s[1:], None))
        m=re.match(r'^&([A-Za-z0-9_-]+)\s*(.*)$', s)
        if m:
            name=m.group(1); rest=m.group(2).strip()
            val=parse_yaml_inline(rest, yp) if rest else None
            yp.anchors[name]=deep_copy(val)
            return val
    if s.startswith('!'):
        parts=s.split(None,1)
        if len(parts)==2: s=parts[1].strip()
    if s.startswith('[') or s.startswith('{'):
        try: return FlowParser(s,'yaml',yp).parse()
        except Exception: pass
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return FlowParser(s,'yaml',yp).parse()
    return parse_yaml_scalar(s, yp, is_key=is_key)

def parse_yaml_inline_seq_from_dash(item, yp):
    # Parse a compact nested dash sequence: "- 2" or "- 2 - 3" (first form mainly).
    vals=[]
    rest=item
    while rest.startswith('- '):
        rest=rest[2:].strip()
        # only first element on the line; common form from emitter.
        vals.append(parse_yaml_inline(rest, yp))
        break
    return vals

def parse_yaml_scalar(s, yp=None, is_key=False):
    s=s.strip()
    if s == '': return ''
    low=s.lower()
    if low in ('null','~'):
        return None
    if low == 'true': return True
    if low == 'false': return False
    if low in ('.inf','+.inf','.infinity','+.infinity'):
        return SpecialFloat('inf')
    if low in ('-.inf','-.infinity'):
        return SpecialFloat('-inf')
    if low in ('.nan','+.nan','-.nan'):
        return SpecialFloat('nan')
    # Date (YAML timestamp) but not for keys in quite the same way? yaml.v2 converts values.
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        return DateVal(s+'T00:00:00Z', s+'T00:00:00Z')
    # Numeric parsing. Avoid treating signs alone as numbers.
    ns=s.replace('_','')
    try:
        if re.match(r'^[+-]?0x[0-9a-fA-F]+$', ns):
            return int(ns,16)
        if re.match(r'^[+-]?0o[0-7]+$', ns):
            return int(ns,8)
        if re.match(r'^[+-]?0[0-9]+$', ns):
            # yaml.v2 accepts leading-zero integers; decimal is close for common cases.
            return int(ns,10)
        if re.match(r'^[+-]?[0-9]+$', ns):
            return int(ns,10)
        if re.match(r'^[+-]?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]+\.[0-9]*[eE][+-]?[0-9]+|[0-9]*\.[0-9]+[eE][+-]?[0-9]+)$', ns):
            return float(ns)
    except Exception:
        pass
    return s

# ----------------------------- YAML emitter -----------------------------

def yaml_needs_double(s):
    if s == '': return True
    low=s.lower()
    if low in ('y','yes','n','no','true','false','on','off','null','~'):
        return True
    if low in ('.nan','.inf','-.inf','+.inf','infinity','-infinity','nan'):
        return True
    if re.match(r'^[+-]?(?:0|[0-9][0-9_]*)(?:\.[0-9_]*)?(?:[eE][+-]?[0-9]+)?$', s):
        return True
    if re.match(r'^[+-]?0x[0-9a-fA-F_]+$', s): return True
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s): return True
    if re.match(r'^\d{1,2}:\d{2}:\d{2}', s): return True
    return False

def yaml_needs_single(s):
    if s[0].isspace() or s[-1].isspace(): return True
    if ': ' in s or s.endswith(':'): return True
    if ' #' in s or s.startswith('#'): return True
    specials = ['- ', '? ', '[', ']', '{', '}', '&', '*', '!', '%', '@', '`']
    for p in specials:
        if s.startswith(p): return True
    return False

def yaml_double(s):
    out='"'
    for ch in s:
        if ch == '"': out+='\\"'
        elif ch == '\\': out+='\\\\'
        elif ch == '\n': out+='\\n'
        elif ch == '\r': out+='\\r'
        elif ch == '\t': out+='\\t'
        elif ch == '\b': out+='\\b'
        elif ch == '\f': out+='\\f'
        elif ord(ch) < 32: out+='\\u%04x'%ord(ch)
        else: out+=ch
    return out+'"'

def yaml_single(s):
    return "'" + s.replace("'", "''") + "'"

def yaml_scalar(v, key=False):
    if isinstance(v, str):
        if '\n' in v and not key:
            return None
        if yaml_needs_double(v): return yaml_double(v)
        if yaml_needs_single(v): return yaml_single(v)
        return v
    if v is None: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int) and not isinstance(v,bool): return str(v)
    if isinstance(v, float): return yaml_float(v)
    if isinstance(v, SpecialFloat):
        return {"inf":".inf","-inf":"-.inf","nan":".nan"}[v.kind]
    if isinstance(v, DateVal): return v.json_text
    return yaml_scalar(key_to_string(v), key)

def is_yaml_inline(v):
    if isinstance(v, Obj): return len(v.pairs)==0
    if isinstance(v, list): return len(v)==0
    if isinstance(v, str) and '\n' in v: return False
    return True

def yaml_inline(v):
    if isinstance(v, Obj): return '{}'
    if isinstance(v, list): return '[]'
    return yaml_scalar(v) or yaml_double(str(v))

def yaml_block_string_lines(s, indent):
    strip = not s.endswith('\n')
    ind=' '*indent
    header='|-' if strip else '|'
    body=s[:-1] if s.endswith('\n') else s
    lines=[header]
    if body == '':
        return lines
    for line in body.split('\n'):
        lines.append(ind+line)
    return lines

def prepare_yaml_keys(v, parse_keys=False):
    if isinstance(v, Obj):
        pairs=[]
        for k,val in v.pairs:
            nk=k
            if parse_keys and isinstance(k,str):
                nk=parse_key_object_for_yaml(k)
                if nk is None:
                    raise RuntimeError('reflect: call of reflect.Value.Set on zero Value')
            pairs.append((nk, prepare_yaml_keys(val, parse_keys)))
        return Obj(pairs)
    if isinstance(v, list): return [prepare_yaml_keys(x, parse_keys) for x in v]
    return v

def parse_key_object_for_yaml(k):
    # Mimic the -k option: parse keys as YAML-ish scalars/flow values, but keep leading-zero ints as strings.
    if re.match(r'^[+-]?0[0-9]+$', k):
        return k
    try:
        return parse_yaml_inline(k, None, is_key=True)
    except Exception:
        return k

def emit_yaml(v, indent=0):
    ind=' '*indent
    if isinstance(v, Obj):
        if not v.pairs: return [ind+'{}']
        lines=[]
        for k,val in v.pairs:
            # complex key
            if isinstance(k,(Obj,list)):
                key_lines=emit_yaml(k, indent+2)
                lines.append(ind+'? '+key_lines[0].lstrip())
                for kl in key_lines[1:]: lines.append(kl)
                if is_yaml_inline(val):
                    lines.append(ind+': '+yaml_inline(val))
                else:
                    lines.append(ind+':')
                    lines.extend(emit_yaml(val, indent+2))
                continue
            ks=yaml_scalar(k, key=True)
            if isinstance(val, str) and '\n' in val:
                bs=yaml_block_string_lines(val, indent+2)
                lines.append(ind+ks+': '+bs[0])
                lines.extend(bs[1:])
            elif is_yaml_inline(val):
                lines.append(ind+ks+': '+yaml_inline(val))
            else:
                lines.append(ind+ks+':')
                lines.extend(emit_yaml(val, indent+2))
        return lines
    if isinstance(v, list):
        if not v: return [ind+'[]']
        lines=[]
        for item in v:
            if isinstance(item, str) and '\n' in item:
                bs=yaml_block_string_lines(item, indent+2)
                lines.append(ind+'- '+bs[0])
                lines.extend(bs[1:])
            elif is_yaml_inline(item):
                lines.append(ind+'- '+yaml_inline(item))
            elif isinstance(item, Obj):
                lines.extend(emit_yaml_obj_seq(item, indent))
            elif isinstance(item, list):
                lines.extend(emit_yaml_list_seq(item, indent))
            else:
                lines.append(ind+'- '+yaml_inline(item))
        return lines
    if isinstance(v, str) and '\n' in v:
        bs=yaml_block_string_lines(v, indent+2)
        return [ind+bs[0]] + bs[1:]
    return [ind+yaml_inline(v)]

def emit_yaml_obj_seq(obj, indent):
    ind=' '*indent
    if not obj.pairs: return [ind+'- {}']
    lines=[]
    first=True
    for k,val in obj.pairs:
        ks=yaml_scalar(k, key=True)
        prefix = ind+'- ' if first else ' '*(indent+2)
        if isinstance(val, str) and '\n' in val:
            bs=yaml_block_string_lines(val, indent+4)
            lines.append(prefix+ks+': '+bs[0]); lines.extend(bs[1:])
        elif is_yaml_inline(val):
            lines.append(prefix+ks+': '+yaml_inline(val))
        else:
            lines.append(prefix+ks+':')
            lines.extend(emit_yaml(val, indent+4))
        first=False
    return lines

def emit_yaml_list_seq(arr, indent):
    ind=' '*indent
    if not arr: return [ind+'- []']
    lines=[]
    first=True
    for item in arr:
        prefix = ind+'- ' if first else ' '*(indent+2)+'- '
        if is_yaml_inline(item):
            lines.append(prefix+yaml_inline(item))
        else:
            lines.append(prefix.rstrip())
            lines.extend(emit_yaml(item, indent+4 if first else indent+4))
        first=False
    return lines

def encode_yaml_doc(v, parse_keys=False):
    if v is EMPTY: return ''
    v=prepare_yaml_keys(v, parse_keys)
    return '\n'.join(emit_yaml(v,0))+'\n'

# ----------------------------- conversions for inf strings -----------------------------

def convert_special_to_strings(v):
    if isinstance(v, SpecialFloat):
        return {"inf":"Infinity","-inf":"-Infinity","nan":"NaN"}[v.kind]
    if isinstance(v, Obj): return Obj([(k, convert_special_to_strings(val)) for k,val in v.pairs])
    if isinstance(v, list): return [convert_special_to_strings(x) for x in v]
    return v

def convert_strings_to_special(v):
    if isinstance(v, str):
        if v == 'Infinity': return SpecialFloat('inf')
        if v == '-Infinity': return SpecialFloat('-inf')
        if v == 'NaN': return SpecialFloat('nan')
        return v
    if isinstance(v, Obj): return Obj([(k, convert_strings_to_special(val)) for k,val in v.pairs])
    if isinstance(v, list): return [convert_strings_to_special(x) for x in v]
    return v

# ----------------------------- TOML parser -----------------------------

class TOMLError(Exception): pass

def strip_toml_comment(line):
    in_s=False; in_d=False; esc=False
    for i,ch in enumerate(line):
        if in_d:
            if esc: esc=False
            elif ch == '\\': esc=True
            elif ch == '"': in_d=False
        elif in_s:
            if ch == "'": in_s=False
        else:
            if ch == '"': in_d=True
            elif ch == "'": in_s=True
            elif ch == '#': return line[:i].rstrip()
    return line.rstrip()

def split_toml_key(s):
    parts=[]; i=0; cur=''; in_s=False; in_d=False; esc=False
    while i < len(s):
        ch=s[i]
        if in_d:
            cur += ch
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
        elif in_s:
            cur += ch
            if ch=="'": in_s=False
        else:
            if ch=='"': in_d=True; cur+=ch
            elif ch=="'": in_s=True; cur+=ch
            elif ch=='.': parts.append(parse_toml_key_part(cur.strip())); cur=''
            else: cur+=ch
        i+=1
    parts.append(parse_toml_key_part(cur.strip()))
    return parts

def parse_toml_key_part(p):
    p=p.strip()
    if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
        return FlowParser(p,'yaml').parse()  # string escape rules close enough
    return p

def find_top_equal(s):
    in_s=False; in_d=False; esc=False; depth=0
    for i,ch in enumerate(s):
        if in_d:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
        elif in_s:
            if ch=="'": in_s=False
        else:
            if ch=='"': in_d=True
            elif ch=="'": in_s=True
            elif ch in '[{': depth+=1
            elif ch in ']}': depth-=1
            elif ch=='=' and depth==0: return i
    return -1

def parse_toml(text):
    root=Obj([]); current=root
    lines=text.replace('\r\n','\n').replace('\r','\n').split('\n')
    i=0
    while i < len(lines):
        raw=lines[i]
        line=strip_toml_comment(raw).strip()
        i+=1
        if line=='': continue
        # collect multiline strings on assignments
        if '=' in line:
            eq=find_top_equal(line)
            if eq>=0:
                valpart=line[eq+1:].lstrip()
                if valpart.startswith('"""') or valpart.startswith("'''"):
                    delim=valpart[:3]
                    collected=[valpart]
                    while collected[-1].count(delim) < 2 and i < len(lines):
                        collected.append(lines[i]); i+=1
                    line=line[:eq+1]+' '+'\n'.join(collected)
        if line.startswith('[[') and line.endswith(']]'):
            path=split_toml_key(line[2:-2].strip())
            current=create_toml_path(root,path,array=True)
            continue
        if line.startswith('[') and line.endswith(']'):
            path=split_toml_key(line[1:-1].strip())
            current=create_toml_path(root,path,array=False)
            continue
        eq=find_top_equal(line)
        if eq < 0:
            raise TOMLError(f"toml: line {i}: expected '.' or '=', but got ':' instead")
        keystr=line[:eq].strip(); valstr=line[eq+1:].strip()
        path=split_toml_key(keystr)
        val=parse_toml_value(valstr)
        set_toml_value(current,path,val,i)
    return root

def create_toml_path(root,path,array=False):
    obj=root
    for p in path[:-1]:
        idx,val=obj_get_pair(obj,p)
        if idx<0:
            val=Obj([]); obj.pairs.append((p,val))
        if isinstance(val,list):
            if not val or not isinstance(val[-1],Obj):
                val.append(Obj([]))
            obj=val[-1]
        elif isinstance(val,Obj): obj=val
        else:
            val=Obj([]); obj.pairs[idx]=(p,val); obj=val
    last=path[-1] if path else ''
    idx,val=obj_get_pair(obj,last)
    if array:
        if idx<0:
            arr=[]; obj.pairs.append((last,arr))
        else: arr=val
        if not isinstance(arr,list): arr=[]; obj.pairs[idx]=(last,arr)
        new=Obj([]); arr.append(new); return new
    else:
        if idx<0:
            new=Obj([]); obj.pairs.append((last,new)); return new
        if isinstance(val,Obj): return val
        new=Obj([]); obj.pairs[idx]=(last,new); return new

def set_toml_value(obj,path,val,line_no):
    cur=obj
    for p in path[:-1]:
        idx,child=obj_get_pair(cur,p)
        if idx<0:
            child=Obj([]); cur.pairs.append((p,child))
        if not isinstance(child,Obj):
            child=Obj([]); cur.pairs[idx]=(p,child)
        cur=child
    key=path[-1]
    idx,_=obj_get_pair(cur,key)
    if idx>=0:
        raise TOMLError(f"toml: line {line_no} (last key \"{key}\"): Key '{key}' has already been defined.")
    cur.pairs.append((key,val))

def parse_toml_value(s):
    s=s.strip()
    if s.startswith('"""') or s.startswith("'''"):
        delim=s[:3]; body=s[3:]
        end=body.rfind(delim)
        if end>=0: body=body[:end]
        if body.startswith('\n'): body=body[1:]
        if delim == '"""':
            return decode_basic_string(body)
        return body
    if s.startswith('"') or s.startswith("'") or s.startswith('[') or s.startswith('{'):
        return TomlValueParser(s).parse()
    return parse_toml_scalar(s)

class TomlValueParser(FlowParser):
    def __init__(self,s): super().__init__(s,'toml')
    def dq(self):
        self.i+=1; out=[]; esc=False
        while self.i < len(self.s):
            ch=self.s[self.i]; self.i+=1
            if esc:
                maps={'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f','"':'"','\\':'\\'}
                if ch == 'u' and self.i+4 <= len(self.s):
                    hx=self.s[self.i:self.i+4]; self.i+=4; out.append(chr(int(hx,16)))
                elif ch == 'U' and self.i+8 <= len(self.s):
                    hx=self.s[self.i:self.i+8]; self.i+=8; out.append(chr(int(hx,16)))
                else: out.append(maps.get(ch,ch))
                esc=False
            elif ch=='\\': esc=True
            elif ch=='"': break
            else: out.append(ch)
        return ''.join(out)
    def sq(self):
        self.i+=1; out=[]
        while self.i < len(self.s):
            ch=self.s[self.i]; self.i+=1
            if ch=="'": break
            out.append(ch)
        return ''.join(out)
    def obj(self):
        self.consume('{'); pairs=[]
        while True:
            self.skip()
            if self.i>=len(self.s): break
            if self.s[self.i]=='}': self.i+=1; break
            key=self.key_token()
            self.skip(); self.consume('=')
            val=self.value()
            pairs.append((key,val))
            self.skip()
            if self.i < len(self.s) and self.s[self.i]==',': self.i+=1; continue
            if self.i < len(self.s) and self.s[self.i]=='}': self.i+=1; break
        return Obj(pairs)
    def key_token(self):
        self.skip()
        if self.i < len(self.s) and self.s[self.i]=='"': return self.dq()
        if self.i < len(self.s) and self.s[self.i]=="'": return self.sq()
        start=self.i
        while self.i < len(self.s) and self.s[self.i] not in '=,}': self.i+=1
        return self.s[start:self.i].strip()

def decode_basic_string(s):
    return TomlValueParser('"'+s+'"').parse()

def parse_toml_scalar(s):
    s=s.strip()
    low=s.lower()
    if low=='true': return True
    if low=='false': return False
    if low in ('inf','+inf'): return SpecialFloat('inf')
    if low=='-inf': return SpecialFloat('-inf')
    if low in ('nan','+nan','-nan'): return SpecialFloat('nan')
    # Date/time/datetime recognition
    if re.match(r'^\d{4}-\d{2}-\d{2}[Tt ][0-9:.]+(?:Z|[+-][0-9:]+)?$', s):
        return DateVal(s, s.replace('t','T').replace(' ', 'T'))
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        return DateVal(s, s+'T00:00:00Z')
    if re.match(r'^\d{2}:\d{2}:\d{2}(?:\.\d+)?$', s):
        return DateVal(s, '0000-01-01T'+s+'Z')
    ns=s.replace('_','')
    try:
        if re.match(r'^[+-]?0x[0-9a-fA-F]+$', ns): return int(ns,16)
        if re.match(r'^[+-]?0o[0-7]+$', ns): return int(ns,8)
        if re.match(r'^[+-]?0b[01]+$', ns): return int(ns,2)
        if re.match(r'^[+-]?[0-9]+$', ns): return int(ns,10)
        if re.match(r'^[+-]?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]+\.[0-9]*[eE][+-]?[0-9]+|[0-9]*\.[0-9]+[eE][+-]?[0-9]+)$', ns): return float(ns)
    except Exception: pass
    return s

# ----------------------------- TOML emitter -----------------------------

def toml_escape(s):
    out='"'
    for ch in s:
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        elif ch=='\b': out+='\\b'
        elif ch=='\f': out+='\\f'
        elif ord(ch)<32: out+='\\u%04x'%ord(ch)
        else: out+=ch
    return out+'"'

def toml_key(k, pos=0):
    k=key_to_string(k)
    if k == '':
        return chr(ord('A') + (pos % 26))
    if re.match(r'^[A-Za-z0-9_-]+$', k): return k
    return toml_escape(k)

def toml_inline(v):
    if v is None: return None
    if isinstance(v, Obj):
        parts=[]
        for i,(k,val) in enumerate(v.pairs):
            tv=toml_inline(val)
            if tv is None: continue
            parts.append(toml_key(k,i)+' = '+tv)
        return '{'+', '.join(parts)+'}'
    if isinstance(v, list):
        parts=[]
        for x in v:
            tx=toml_inline(x)
            if tx is not None: parts.append(tx)
        return '['+', '.join(parts)+']'
    if isinstance(v, str): return toml_escape(v)
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int) and not isinstance(v,bool): return str(v)
    if isinstance(v, float): return toml_float(v)
    if isinstance(v, SpecialFloat): return {"inf":"+inf","-inf":"-inf","nan":"nan"}[v.kind]
    if isinstance(v, DateVal): return v.toml_text
    return toml_escape(str(v))

def is_array_of_objs(v):
    return isinstance(v,list) and len(v)>0 and all(isinstance(x,Obj) for x in v)

def encode_toml(v, indent=False):
    if v is EMPTY: return ''
    if not isinstance(v, Obj):
        tv=toml_inline(v)
        return '' if tv is None else tv
    lines=[]
    write_toml_obj(v, [], lines, indent, 0)
    return ('\n'.join(lines)+'\n') if lines else ''

def write_toml_obj(obj, prefix, lines, indent_flag, depth):
    table_items=[]; array_items=[]
    # scalar pass
    for i,(k,val) in enumerate(obj.pairs):
        if val is None: continue
        if isinstance(val, Obj):
            table_items.append((i,k,val)); continue
        if is_array_of_objs(val):
            array_items.append((i,k,val)); continue
        tv=toml_inline(val)
        if tv is None: continue
        pref='  '*depth if indent_flag and prefix else ''
        lines.append(pref+toml_key(k,i)+' = '+tv)
    # tables in original order after scalars
    for i,k,val in table_items:
        if lines and (not prefix): lines.append('')
        header='['+'.'.join(toml_key(x,0) for x in prefix+[k])+']'
        pref='  '*depth if indent_flag and prefix else ''
        lines.append(pref+header)
        write_toml_obj(val, prefix+[k], lines, indent_flag, depth+1)
    for i,k,arr in array_items:
        for objv in arr:
            if lines: lines.append('')
            header='[['+'.'.join(toml_key(x,0) for x in prefix+[k])+']]'
            pref='  '*depth if indent_flag and prefix else ''
            lines.append(pref+header)
            write_toml_obj(objv, prefix+[k], lines, indent_flag, depth+1)

# ----------------------------- HCL parser -----------------------------

@dataclass
class Tok:
    typ: str
    val: str

class HCLParseError(Exception): pass

class HCLTokenizer:
    def __init__(self,text):
        self.text=text; self.i=0; self.tokens=[]; self.tokenize(); self.pos=0
    def tokenize(self):
        s=self.text; i=0; n=len(s)
        while i<n:
            ch=s[i]
            if ch.isspace(): i+=1; continue
            if ch=='#':
                while i<n and s[i]!='\n': i+=1
                continue
            if ch=='/' and i+1<n and s[i+1]=='/':
                i+=2
                while i<n and s[i]!='\n': i+=1
                continue
            if ch=='/' and i+1<n and s[i+1]=='*':
                i+=2
                while i+1<n and not (s[i]=='*' and s[i+1]=='/'): i+=1
                i+=2; continue
            if ch in '{}[]=,': self.tokens.append(Tok(ch,ch)); i+=1; continue
            if ch=='"':
                j=i+1; out=[]; esc=False
                while j<n:
                    c=s[j]; j+=1
                    if esc:
                        maps={'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f','"':'"','\\':'\\'}
                        out.append(maps.get(c,c)); esc=False
                    elif c=='\\': esc=True
                    elif c=='"': break
                    else: out.append(c)
                self.tokens.append(Tok('STRING',''.join(out))); i=j; continue
            if ch.isdigit() or ch in '+-.':
                j=i+1
                while j<n and re.match(r'[A-Za-z0-9_+\-.]', s[j]): j+=1
                self.tokens.append(Tok('ATOM',s[i:j])); i=j; continue
            if re.match(r'[A-Za-z_]', ch):
                j=i+1
                while j<n and re.match(r'[A-Za-z0-9_\-./]', s[j]): j+=1
                self.tokens.append(Tok('IDENT',s[i:j])); i=j; continue
            raise HCLParseError(f"At 1:{i+1}: illegal char")
        self.tokens.append(Tok('EOF',''))
    def peek(self): return self.tokens[self.pos]
    def get(self): t=self.tokens[self.pos]; self.pos+=1; return t
    def accept(self,typ):
        if self.peek().typ==typ: return self.get()
        return None
    def expect(self,typ):
        if self.peek().typ!=typ: raise HCLParseError(f"expected: {typ} got: {self.peek().typ}")
        return self.get()

def parse_hcl(text):
    stripped=text.strip()
    if stripped=='': return EMPTY
    if stripped.startswith('{') or stripped.startswith('['):
        # HCL accepts JSON documents in many cases; use JSON parser as a useful subset.
        return parse_json_text(text)
    tz=HCLTokenizer(text)
    obj=parse_hcl_body(tz, top=True)
    return obj

def parse_hcl_body(tz, top=False):
    obj=Obj([])
    while tz.peek().typ not in ('EOF','}'):
        t=tz.get()
        if t.typ not in ('IDENT','STRING'):
            raise HCLParseError(f"At 1:1: illegal char")
        name=t.val
        if tz.peek().typ == '=':
            tz.get(); val=parse_hcl_value(tz, assignment=True); obj.pairs.append((name,val))
        else:
            labels=[]
            while tz.peek().typ in ('IDENT','STRING','ATOM'):
                labels.append(tz.get().val)
            tz.expect('{')
            body=parse_hcl_body(tz)
            tz.expect('}')
            insert_hcl_block(obj,name,labels,body)
        tz.accept(',')
    return obj

def parse_hcl_value(tz, assignment=False):
    t=tz.peek()
    if t.typ=='STRING': tz.get(); return t.val
    if t.typ in ('IDENT','ATOM'):
        tz.get(); return parse_hcl_scalar(t.val)
    if t.typ=='[':
        tz.get(); arr=[]
        while tz.peek().typ not in (']','EOF'):
            arr.append(parse_hcl_value(tz))
            tz.accept(',')
        tz.expect(']'); return arr
    if t.typ=='{':
        tz.get(); body=parse_hcl_body(tz); tz.expect('}')
        return [body] if assignment else body
    raise HCLParseError(f"unexpected token {t.typ}")

def parse_hcl_scalar(s):
    low=s.lower()
    if low=='true': return True
    if low=='false': return False
    if low=='null': return None
    try:
        if re.match(r'^[+-]?[0-9]+$', s): return int(s)
        if re.match(r'^[+-]?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]+\.[0-9]*[eE][+-]?[0-9]+|[0-9]*\.[0-9]+[eE][+-]?[0-9]+)$', s): return float(s)
    except Exception: pass
    return s

def insert_hcl_block(obj,name,labels,body):
    idx,arr=obj_get_pair(obj,name)
    if idx<0 or not isinstance(arr,list):
        arr=[]; obj.pairs.append((name,arr))
    if not labels:
        arr.append(body); return
    if not arr or not isinstance(arr[0],Obj): arr.append(Obj([]))
    insert_hcl_labels(arr[0], labels, body)

def insert_hcl_labels(obj, labels, body):
    lab=labels[0]
    idx,arr=obj_get_pair(obj,lab)
    if idx<0 or not isinstance(arr,list):
        arr=[]; obj.pairs.append((lab,arr))
    if len(labels)==1:
        arr.append(body)
    else:
        if not arr or not isinstance(arr[0],Obj): arr.append(Obj([]))
        insert_hcl_labels(arr[0], labels[1:], body)

# ----------------------------- HCL emitter -----------------------------

def hcl_string(s):
    return json_escape_string(s, escape_html=False)

def hcl_scalar(v):
    if isinstance(v,str): return hcl_string(v)
    if v is None: return ''
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float): return go_float_json(v)
    if isinstance(v,SpecialFloat):
        if v.kind=='nan': return 'null'
        return '1.7976931348623157e+308' if v.kind=='inf' else '-1.7976931348623157e+308'
    if isinstance(v,DateVal): return hcl_string(v.json_text)
    return hcl_string(str(v))

def hcl_token_desc(v):
    if isinstance(v,list): return 'LBRACK ['
    if isinstance(v,Obj): return 'LBRACE {'
    if v is None: return 'NULL null'
    if isinstance(v,bool): return 'BOOL '+('true' if v else 'false')
    if isinstance(v,(int,float)): return 'NUMBER '+(go_float_json(v) if isinstance(v,float) else str(v))
    if isinstance(v,str): return 'STRING '+hcl_string(v)
    return 'unknown'

def encode_hcl(v):
    if v is EMPTY: return ''
    if not isinstance(v, Obj):
        raise RuntimeError('Expected object, got unknown token: 1:1 '+hcl_token_desc(v))
    if not v.pairs: return ''
    blocks=[]
    for k,val in v.pairs:
        blocks.extend(hcl_attr_blocks(k,val,0))
    return '\n\n'.join(blocks)

def hcl_attr_blocks(k,val,indent):
    ind=' '*indent; key=hcl_string(key_to_string(k))
    if isinstance(val, Obj):
        return [ind+key+' = '+hcl_obj_value(val, indent)]
    if isinstance(val, list):
        if all(isinstance(x,Obj) for x in val) and val:
            return [ind+key+' = '+hcl_obj_value(x, indent) for x in val]
        return [ind+key+' = '+hcl_list_value(val)]
    return [ind+key+' = '+hcl_scalar(val)]

def hcl_obj_value(obj, indent):
    if not obj.pairs: return '{}'
    inner=[]
    for k,val in obj.pairs:
        inner.extend(hcl_attr_blocks(k,val,indent+2))
    return '{\n' + '\n\n'.join(inner) + '\n' + ' '*indent + '}'

def hcl_list_value(arr):
    if not arr: return '[]'
    if any(x is None for x in arr):
        raise RuntimeError('unexpected token while parsing list: NULL')
    if len(arr)==1 and isinstance(arr[0],list):
        return hcl_list_value(arr[0])
    if any(isinstance(x,Obj) for x in arr):
        raise RuntimeError('expected: STRING got: LBRACE')
    if any(isinstance(x,list) for x in arr):
        raise RuntimeError('expected: STRING got: LBRACK')
    parts=[]
    for x in arr:
        if isinstance(x,bool):
            continue
        parts.append(hcl_scalar(x))
    return '['+', '.join(parts)+']'

# ----------------------------- main -----------------------------

def decode_input(src, text):
    if src == 'j':
        return parse_json_text(text)
    if src == 'y':
        return YAMLParser(text).parse()
    if src == 't':
        return parse_toml(text)
    if src == 'c':
        return parse_hcl(text)
    return EMPTY

def encode_output(dst, data, opts):
    # Conversion of Infinity/NaN strings for YAML/TOML output unless -n.
    outdata=data
    if dst in ('y','t') and not opts.get('n'):
        outdata=convert_strings_to_special(outdata)
    if dst == 'j':
        return encode_json(outdata, escape_html=opts.get('e'), indent=(2 if opts.get('i') else None))+'\n'
    if dst == 'y':
        return encode_yaml_doc(outdata, parse_keys=opts.get('k'))
    if dst == 't':
        return encode_toml(outdata, indent=opts.get('i'))
    if dst == 'c':
        return encode_hcl(outdata)
    return ''

def main(argv):
    invalid, opts, src, dst = parse_flags(argv)
    prog = argv[0] if argv else './executable'
    if invalid:
        sys.stderr.write(usage(prog)+"\n")
        sys.stderr.write("Error: invalid flags specified: "+' '.join(invalid)+"\n")
        return 1
    if opts.get('k') and dst != 'y':
        sys.stderr.write(usage(prog)+"\n")
        sys.stderr.write("Error: flag -k only valid for YAML output\n")
        return 1
    if opts.get('i') and dst not in ('j','t'):
        sys.stderr.write(usage(prog)+"\n")
        sys.stderr.write("Error: flag -i only valid for JSON or TOML output\n")
        return 1
    if opts.get('h'):
        sys.stdout.write(usage(prog)+"\n")
        return 0
    if opts.get('v'):
        sys.stdout.write(VERSION+'\n')
        return 0
    text=sys.stdin.read()
    try:
        data=decode_input(src,text)
        if src in ('y','t') and not opts.get('n'):
            data=convert_special_to_strings(data)
    except JSONParseError as e:
        sys.stderr.write('Error parsing JSON: '+str(e)+'\n'); return 1
    except TOMLError as e:
        sys.stderr.write('Error parsing TOML: '+str(e)+'\n'); return 1
    except HCLParseError as e:
        sys.stderr.write('Error parsing HCL: '+str(e)+'\n'); return 1
    except YAMLParseError as e:
        sys.stderr.write('Error parsing YAML: '+str(e)+'\n'); return 1
    except Exception as e:
        # Keep parser failures close to yj's terse style.
        label={'j':'JSON','y':'YAML','t':'TOML','c':'HCL'}.get(src,'input')
        sys.stderr.write(f'Error parsing {label}: {e}\n'); return 1
    try:
        out=encode_output(dst,data,opts)
        sys.stdout.write(out)
        return 0
    except RuntimeError as e:
        label={'j':'JSON','y':'YAML','t':'TOML','c':'HCL'}.get(dst,'output')
        sys.stderr.write(f'Error writing {label}: {e}\n'); return 1
    except Exception as e:
        label={'j':'JSON','y':'YAML','t':'TOML','c':'HCL'}.get(dst,'output')
        sys.stderr.write(f'Error writing {label}: {e}\n'); return 1

if __name__ == '__main__':
    sys.exit(main(sys.argv))
